using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Register the classifier service as a singleton (holds trained model metrics)
builder.Services.AddSingleton<TicketClassifierService>();

var app = builder.Build();

// Train the model at startup and register the PredictionEnginePool
var classifierService = app.Services.GetRequiredService<TicketClassifierService>();
var modelPath = classifierService.TrainAndEvaluate();

// Register PredictionEnginePool from the trained model file (thread-safe pooling)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

// Rebuild the app with prediction pool registered
app = builder.Build();

app.MapControllers();
app.Run();

