using System.Text;
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketClassifierService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _modelPath;
    private readonly string _dataPath;
    private readonly ILogger<TicketClassifierService> _logger;
    private ModelMetrics? _metrics;

    // Category labels in the order ML.NET assigns them (alphabetical)
    private static readonly string[] CategoryLabels = ["Billing", "General", "Technical"];

    public ModelMetrics? Metrics => _metrics;

    public TicketClassifierService(ILogger<TicketClassifierService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    public string TrainAndEvaluate()
    {
        _logger.LogInformation("Loading training data from {Path}", _dataPath);

        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label")
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        _logger.LogInformation("Evaluating model on test set...");
        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _metrics = new ModelMetrics
        {
            MicroAccuracy = metrics.MicroAccuracy,
            MacroAccuracy = metrics.MacroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
            PerClassMetrics = FormatPerClassMetrics(metrics),
        };

        _logger.LogInformation(
            "Model evaluation — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        // Retrain on full dataset for production model
        var fullModel = pipeline.Fit(data);
        _mlContext.Model.Save(fullModel, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        return _modelPath;
    }

    public VBuffer<ReadOnlyMemory<char>> GetLabelSlotNames()
    {
        if (!File.Exists(_modelPath))
            return default;

        var model = _mlContext.Model.Load(_modelPath, out _);
        var schema = model.GetOutputSchema(SchemaDefinition.Create(typeof(TicketInput)));

        if (schema["Score"]?.Type is Microsoft.ML.Data.VectorDataViewType vectorType)
        {
            var slotNames = new VBuffer<ReadOnlyMemory<char>>();
            schema["Score"].GetSlotNames(ref slotNames);
            return slotNames;
        }

        return default;
    }

    private static string FormatPerClassMetrics(Microsoft.ML.Data.MulticlassClassificationMetrics metrics)
    {
        var sb = new StringBuilder();
        var perClass = metrics.PerClassLogLoss;
        for (int i = 0; i < perClass.Count && i < CategoryLabels.Length; i++)
        {
            sb.AppendLine($"  {CategoryLabels[i]}: LogLoss={perClass[i]:F4}");
        }
        return sb.ToString();
    }
}

